import{_ as a,o as s,c as t,b6 as e,gE as l,gF as r,gG as h,gH as p,gI as n,gJ as o,gK as d,gL as g,gM as c,gN as b,gO as u,gP as k,gQ as m,gR as G,gS as H,gT as S,gU as F,gV as y,gW as f,gX as _,gY as E}from"./chunks/framework.BUXTSoD9.js";const D=JSON.parse('{"title":"GitとGitHubワークフロー","description":"","frontmatter":{},"headers":[],"relativePath":"ja-jp/stage-2/backend/git-workflow/index.md","filePath":"ja-jp/stage-2/backend/git-workflow/index.md"}'),C={name:"ja-jp/stage-2/backend/git-workflow/index.md"};function x(P,i,B,T,v,A){return s(),t("div",null,[...i[0]||(i[0]=[e('<h1 id="gitとgithubワークフロー" tabindex="-1">GitとGitHubワークフロー <a class="header-anchor" href="#gitとgithubワークフロー" aria-label="Permalink to “GitとGitHubワークフロー”">​</a></h1><p>前のコースでは、Webベースのvibe codingツールを使ってコードを書く方法を学びました。毎回の対話で新しいバージョンのコードが作成されます。しかし、一つ考えてみましょう：以前の修正に戻りたい場合、便利な方法はあるでしょうか？異なる段階のコードを記録し、いつでも異なるバージョン間で切り替えや修正ができるツールはあるでしょうか？</p><p>このニーズを満たすために、バージョン管理ソフトウェアが誕生しました。本記事では、最も有名なバージョン管理プログラム——Git——と、最も優れたコードホスティングプラットフォーム——GitHub——を紹介します。Gitを使ったコード管理、GitHubから他人のコードの取得、自分のコードのアップロード、そして他の人との協業による大規模プロジェクトの進め方を学びます。</p><p>個人プロジェクトのバージョン追跡、チーム協業でのコード同期、オープンソースコミュニティへの貢献のいずれにおいても、GitとGitHubはモダンな開発者にとって必須のツールです。これらをマスターすることで、コードをより効率的に管理し、必要に応じてチェックポイントを作成し、コードの異なる段階間を自由に切り替え、単一ファイルの変更から大規模プロジェクトの開発まで、すべてを簡単に処理できるようになります——コードの毎回のイテレーションを管理可能かつトレース可能にします。</p><blockquote><p>💡 <strong>前提知識</strong></p><p>Gitを学ぶ前に、以下の概念を先に理解しておくことをお勧めします：</p><ul><li><a href="/easy-vibe-ja-learning-map/ja-jp/appendix/2-development-tools/command-line-shell.html">ターミナル/コマンドラインとは</a> - コマンドラインを使ったコンピュータとのやり取りを学ぶ</li><li><a href="/easy-vibe-ja-learning-map/ja-jp/appendix/2-development-tools/git-version-control.html">Gitとは</a> - Gitバージョン管理システムの核心概念を理解</li></ul><p>本記事ではGitHubワークフローと実際の操作に焦点を当て、上記の基礎知識については付録のリンクを参照してください。</p></blockquote><h1 id="gitクイックスタート" tabindex="-1">Gitクイックスタート <a class="header-anchor" href="#gitクイックスタート" aria-label="Permalink to “Gitクイックスタート”">​</a></h1><p>Gitを使い始める前に、付録の<a href="/easy-vibe-ja-learning-map/ja-jp/appendix/2-development-tools/command-line-shell.html">コマンドライン</a>と<a href="/easy-vibe-ja-learning-map/ja-jp/appendix/2-development-tools/git-version-control.html">Git基礎</a>の内容をすでに読んでいることを確認してください。本記事はこれらの基礎知識があることを前提に、Gitのインストール・設定とGitHubを使った協業の方法を直接説明します。</p><h2 id="gitのインストール方法" tabindex="-1">Gitのインストール方法 <a class="header-anchor" href="#gitのインストール方法" aria-label="Permalink to “Gitのインストール方法”">​</a></h2><p>異なるコンピュータのオペレーティングシステムにGitをインストールする3つの方法をデモします。自分のシステムバージョンに応じて手順に従ってください：</p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to “Windows”">​</a></h3><ol><li><p><a href="https://git-scm.com/download/win" target="_blank" rel="noreferrer">Git公式ダウンロードページ</a>にアクセスし、自分のシステムに合ったインストーラーをダウンロード：<a href="https://github.com/git-for-windows/git/releases/download/v2.51.0.windows.1/Git-2.51.0-64-bit.exe" target="_blank" rel="noreferrer">インストーラー</a>。デフォルトではx64インストーラーの使用を推奨。</p></li><li><p>インストーラーをダブルクリックし、インストールウィザードの指示に従う： <img src="'+l+'" alt=""></p><ol><li>デフォルトのオプションを維持することをお勧めします。カスタマイズが必要な場合は以下に注意：（ほとんどの場合、「Next」をクリックし続ければ問題ありません） <ul><li>Gitが使用するデフォルトエディタを選択：お好みのエディタ（例：VS Code）を選択。最初のオプションであるVim（テキストエディタ）をデフォルトとして選択するか、「Visual Studio Code as Git&#39;s default editor」オプション（VS Codeの事前インストールが必要）を選択できます。デフォルトのまま「Next」をクリックして続行できます。 <img src="'+r+'" alt=""></li><li>Gitの使用方法を選択：これら3つのオプションは、システム内でのGitのアクセシビリティを制御します。オプション2（&quot;from command line and 3rd-party software&quot;）の選択をお勧めします——基本的なGitツールをPATHに追加し、Git Bash、コマンドプロンプト、PowerShell、IDEでGitを使用できるようにしますが、システムを汚しません。 <img src="'+h+'" alt=""></li></ul></li></ol></li><li><p>インストール後、デスクトップで右クリック。メニューに「Git Bash Here」が表示されていれば、インストール成功です。</p></li></ol><p><img src="'+p+`" alt=""></p><h3 id="macos" tabindex="-1">MacOS <a class="header-anchor" href="#macos" aria-label="Permalink to “MacOS”">​</a></h3><p>macOSの場合、まずターミナルで<code>git --version</code>と入力して、Gitがすでにインストールされているか確認できます。インストールされていない場合、インストールを促すメッセージが表示されます——指示に従ってインストールを完了してください。</p><ol><li>方法1：Homebrewでインストール <a href="https://brew.sh/" target="_blank" rel="noreferrer">Homebrew</a>（Macパッケージマネージャー）がインストールされている場合、ターミナルを開いて以下を入力<div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span></span></code></pre></div></li><li>方法2：（推奨）Xcodeでインストール： <a href="https://developer.apple.com/xcode/" target="_blank" rel="noreferrer">https://developer.apple.com/xcode/</a> 、XcodeにはGitが内蔵されています。インストール後、指示に従って続行してください。</li></ol><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to “Linux”">​</a></h3><p>ほとんどのLinuxディストリビューションはパッケージマネージャーでGitをインストールできます：</p><ul><li>Ubuntu/Debian:</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span></span></code></pre></div><ul><li>CentOS/RHEL:</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span></span></code></pre></div><ul><li>インストールの確認：ターミナルでgit --versionと入力。バージョン番号が表示されればインストール成功です。</li></ul><h2 id="gitの初期化" tabindex="-1">Gitの初期化 <a class="header-anchor" href="#gitの初期化" aria-label="Permalink to “Gitの初期化”">​</a></h2><p>Gitをインストールした後、まずユーザー情報を設定する必要があります——これはGitを使ったバージョン管理の基本ステップです。ターミナルで以下のコマンドを実行してください（括弧内の内容は自分の情報に置き換えてください）：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># グローバルユーザー名を設定（コミット記録に表示される）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Your Name&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># グローバルメールアドレスを設定（GitHub/GitLabなどのプラットフォームで登録したメールアドレスの使用を推奨）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;your.email@example.com&quot;</span></span></code></pre></div><p>Gitはこの情報を各コミット記録に組み込み、毎回の修正の「作者情報」として使用します。バージョン履歴（例：git logを使用）を確認する際、誰がどの行のコードを修正したかが明確にわかり、責任の追跡とコミュニケーションに便利です。協業プロジェクトでは、統一されたID情報により、チームメンバーが誰がどの変更を行ったかを迅速に特定でき、協業効率が向上します（例：コミット記録から関連する開発者を見つけて問題を議論するなど）。</p><p>コマンドラインで<code>git config --list</code>と入力することで、現在のGit設定情報を確認し、設定が成功したか確認できます。</p><h1 id="githubとは" tabindex="-1">GitHubとは <a class="header-anchor" href="#githubとは" aria-label="Permalink to “GitHubとは”">​</a></h1><p>GitHubはGitベースのコードホスティングプラットフォームです。Gitリポジトリのリモートストレージを提供するだけでなく、協業ツール（Issues、Pull Requests、Projectsなど）も含み、開発者がコードを共有し協業しやすくします。簡単に言えば、Gitはローカルバージョン管理ツールであり、GitHubはリモートの「コードリポジトリクラウド + 協業コミュニティ」です。</p><p>GitHubは世界最大のコードホスティングプラットフォームであるだけでなく、世界で最も活発で影響力のあるオープンソースコミュニティです。ここでの「オープンソース」の核心的な考え方は、誰でもソフトウェアのソースコードをダウンロードして実行できるということです。このモデルにより、世界中の人々が互いのコードを検査して修正したり、それに基づいて新しいプロジェクトを作成したりできます。例えば、GitHubで各種学習チュートリアルや、GPTモデルのトレーニングに使用されるフレームワーク（PyTorchなど）の完全なソースコードを見つけることができます。毎日、世界中で無数の人がコードをレビューし改善するために協業しています。</p><p><img src="`+n+'" alt=""></p><p>多くの大企業がGitHubでプログラムやチュートリアルをオープンソース化し、業界での競争優位性を得ています——これは一種の広告形態とも言えます。GitHubコミュニティでは、プロジェクトが獲得した「スター（stars）」の数がその価値を測る主な指標であり、プロジェクトや組織が持つスターが多いほど、その信頼性と影響力が大きくなります。</p><p><img src="'+o+'" alt=""></p><p>本コースでは、サポートリソースや課題も専用のGitHubリポジトリにアップロードされます。課題のアップロードプロセスを通じて、GitHubの使用に徐々に慣れ親しみマスターし、将来のアプリケーション開発におけるバージョン管理の基盤を築きます。</p><h2 id="githubアカウントの登録" tabindex="-1">GitHubアカウントの登録 <a class="header-anchor" href="#githubアカウントの登録" aria-label="Permalink to “GitHubアカウントの登録”">​</a></h2><ol><li><a href="https://github.com/" target="_blank" rel="noreferrer">GitHub公式サイト</a>にアクセスし、右上の「Sign up」をクリック。 <img src="'+d+'" alt=""></li><li>メールアドレスを入力（検証や通知がそこに送信されるため、常用メールの使用を推奨）、パスワードを設定（文字、数字、特殊文字を含める必要があります）。</li><li>人工検証を完了し、指示に従ってメールを検証すれば、アカウントの作成完了です。</li></ol><h2 id="githubで最初のリポジトリを作成" tabindex="-1">GitHubで最初のリポジトリを作成 <a class="header-anchor" href="#githubで最初のリポジトリを作成" aria-label="Permalink to “GitHubで最初のリポジトリを作成”">​</a></h2><p>次に、最初の保存フォルダー、すなわちリポジトリまたは「repo」を作成します。</p><p><img src="'+g+'" alt=""><img src="'+c+'" alt=""></p><p><img src="'+b+'" alt=""></p><ol><li>Repository name：他人に表示されるリポジトリ名。</li><li>Description：リポジトリの詳細な説明。</li><li>Choose visibility：個人リポジトリの場合、privateに設定すると、自分と特別に招待された人のみが閲覧可能。publicに設定すると、誰でも閲覧可能。 組織内のリポジトリの場合、Privateにすると組織内の人のみが閲覧可能。 Publicにすると組織外の人も閲覧可能。</li><li>README：一般的に、すべてのリポジトリにREADMEファイルがあることが推奨されます。これはリポジトリの完全な紹介と考えられ、使用説明、ファイルリスト、操作方法などが含まれます。</li><li>Add .gitignore and license： <ol><li>.gitignoreファイルは、GitにGitHubへのアップロード時に特定のフォルダやファイルを無視するよう指示し、それらが追跡やステージングエリアに追加されないようにします。これは一時テストファイル、依存パッケージ、大きなファイルに便利です。指定すると、これらのファイルは追跡されなくなります。</li><li>licenseは、選択するオープンソースライセンスのタイプを指します。異なるライセンスは、他人があなたのコードを商用目的で使用できるかどうかなどを詳細に規定し、他の条項や条件も含みます。</li></ol></li></ol><p>「Add README」にチェックを入れ、リポジトリの可視性を「Private」に設定し、リポジトリ名と説明をお好みで入力してから「Create repository」をクリックして最初のリモートリポジトリの作成を完了することをお勧めします。</p><p><img src="'+u+'" alt=""></p><p>その後、余分なファイルのないクリーンなリポジトリが手に入ります。次にファイルのアップロードを始められます。</p><p><img src="'+k+'" alt=""></p><p>リポジトリを取得するコマンドは<code>git clone</code>ですが、リポジトリのアドレスが必要です。緑色の「Code」ボタンをクリックしてリポジトリのアドレスを見つけられます。HTTPSとSSHのオプションが表示されます。通常、どちらの方法でもリポジトリをローカルマシンにダウンロードできます（そうして初めてファイルの修正とアップロードが可能になります）。</p><p><img src="'+m+'" alt=""></p><p>一般的に、HTTPでクローンしたリポジトリは他人のリポジトリを一時的にダウンロードしてテストするのに適していますが、自分の開発にはお勧めしません。より良い学習体験のために、まずSSH認証を設定してください。</p><h2 id="ローカルsshのバインド" tabindex="-1">ローカルSSHのバインド <a class="header-anchor" href="#ローカルsshのバインド" aria-label="Permalink to “ローカルSSHのバインド”">​</a></h2><p>GitHubにおける「SSHプロトコルバインド」とは、本質的にローカルデバイスのSSH公開鍵をGitHubアカウントに関連付け、GitHubがSSHプロトコルを通じてデバイスを識別できるようにすることです。これにより、パスワードなしでリモートリポジトリを安全に操作（clone、push、pullコードなど）できるようになります。</p><p>簡単に言えば：これはデバイスに「GitHub専用のセキュリティカード」を与えるようなものです。バインド後、デバイスがSSHプロトコルでGitHubリポジトリにアクセスする際、GitHubはこの「セキュリティカード」（あなたのSSH公開鍵）を検証します。あなたの認可されたデバイスであることが確認されれば、直接操作できます——毎回アカウントのパスワードを入力する必要はありません。</p><blockquote><p>💡 SSHとは</p></blockquote><h3 id="なぜsshプロトコルのバインドが必要なのか" tabindex="-1">なぜSSHプロトコルのバインドが必要なのか？ <a class="header-anchor" href="#なぜsshプロトコルのバインドが必要なのか" aria-label="Permalink to “なぜSSHプロトコルのバインドが必要なのか？”">​</a></h3><p>GitHubは主に2つのリポジトリ操作プロトコルをサポートしています：HTTPSプロトコルとSSHプロトコル：</p><ul><li>HTTPSプロトコル：毎回の操作（pushなど）でGitHubのアカウントパスワード（またはPersonal Access Token）の入力が必要。検証プロセスが煩雑で、パスワード漏洩のリスクもあります。</li><li>SSHプロトコル：認証は「鍵ペア」で完了するため、パスワードの繰り返し入力が不要で、暗号化転送もより安全です。</li></ul><p>「SSHプロトコルバインド」はGitHubのSSH認証を有効にするための前提ステップです——ローカルのSSH公開鍵をGitHubアカウントに「バインド」して初めて、GitHubはあなたのデバイスを識別し、リポジトリのSSH操作を許可します。</p><h3 id="「バインド」の核心的なロジック-ssh鍵ペアの役割" tabindex="-1">「バインド」の核心的なロジック：SSH鍵ペアの役割 <a class="header-anchor" href="#「バインド」の核心的なロジック-ssh鍵ペアの役割" aria-label="Permalink to “「バインド」の核心的なロジック：SSH鍵ペアの役割”">​</a></h3><p>SSH認証は鍵ペア（公開鍵 + 秘密鍵）に依存しており、これらは一致する暗号化ファイルです。生成後、「公開鍵」をGitHubに提供（「バインド」）し、「秘密鍵」はローカルデバイスに残します：</p><ol><li>秘密鍵：ローカルデバイス（PCなど）の指定されたディレクトリ（通常は~/.ssh/）に保存され、「あなた専用の鍵」として機能し、誰とも共有してはいけません。</li><li>公開鍵：これは公開して共有できる「鍵」です——GitHubアカウントの「SSH keys list」にコピー（「バインド」操作）する必要があります。</li></ol><p>SSHでGitHubリポジトリを操作する際（例：git push <a href="mailto:git@github.com" target="_blank" rel="noreferrer">git@github.com</a>:xxx/xxx.git）：</p><ul><li>ローカルデバイスが秘密鍵を使って「操作リクエスト」を暗号化しGitHubに送信；</li><li>リクエストを受信したGitHubは、以前にバインドした公開鍵を使って復号を試みる；</li><li>復号が成功すれば、デバイスは認可されたものとして確認され、操作が許可される。そうでない場合、アクセスは拒否されます。</li></ul><h3 id="「バインド」の具体的な手順-核心的なフロー" tabindex="-1">「バインド」の具体的な手順（核心的なフロー） <a class="header-anchor" href="#「バインド」の具体的な手順-核心的なフロー" aria-label="Permalink to “「バインド」の具体的な手順（核心的なフロー）”">​</a></h3><p>原理を理解すれば、実際の操作はシンプルです——核心は「鍵ペアの生成 → 公開鍵のGitHubへのアップロード」です：</p><ol><li><p>ローカルでSSH鍵ペアを生成</p><ol><li>Traeを使って公開鍵を取得（推奨） プロンプト：<code>Help me create the SSH key needed for GitHub login. My email is your_email@gmail.com , Please return the public key for me to copy</code></li></ol><p><img src="'+G+'" alt=""></p><p>プロンプトを入力した後、左側のターミナルでEnterキーを押す必要があります。そうしないとコマンドが待機状態のままになります。Traeは条件判断を実行できないため、ひたすらEnterを押し続けるだけで問題ありません。</p><p>最終的に、右側のTraeが読み取った公開鍵が返されます。それをコピーし、次のステップで貼り付ける準備をしてください。</p><p><img src="'+H+'" alt=""> 2. 手動で公開鍵を取得 ローカルのターミナルを開き（WindowsではGit BashまたはPowerShell、macOS/Linuxではターミナル）、以下のコマンドを入力（your_email@example.comをGitHubアカウント登録時に使用したメールアドレスに置き換えてください）：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ed25519</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;your_email@example.com&quot;</span></span></code></pre></div><ol><li>Enterを押してデフォルト値を受け入れる（デフォルトのファイルパス、パスワードなし、または必要に応じてパスワードを設定）。これで~/.ssh/ディレクトリに2つのファイルが生成されます： <ul><li>id_ed25519：秘密鍵（ローカルに保存、<strong>絶対に共有しない</strong>）；</li><li>id_ed25519.pub：公開鍵（GitHubにアップロードが必要）。</li></ul></li></ol></li><li><p>公開鍵をGitHubアカウントに「バインド」</p></li></ol><p>これが核心的なバインドステップです——ローカルの公開鍵をGitHubアカウントの「SSH keys list」に追加：</p><ol><li>公開鍵の内容をコピー： <ol><li>Trae：</li><li>Windows：メモ帳でC:\\Users&lt;your&gt;.ssh\\id_ed25519.pubを開き、全内容をコピー；</li><li>macOS/Linux：ターミナルでcat ~/.ssh/id_ed25519.pubを実行し、全出力をコピー（先頭のSSH-ed25519から末尾のメールアドレスまで）。</li></ol></li><li>GitHubにログインし「SSH Key Management」ページに進む： <ol><li>右上のアバターをクリック → Settings → 左側のメニューSSH and GPG keys → New SSH keyをクリック。 <img src="'+S+'" alt=""><img src="'+F+'" alt=""></li><li>任意のタイトルを入力（例：your local computer&#39;s SSH）し、取得したSSH公開鍵をここに貼り付け。</li></ol></li></ol><p><img src="'+y+'" alt=""></p><p><img src="'+f+'" alt=""></p><ol start="3"><li>バインドの成功を確認</li></ol><p>ターミナルで以下のコマンドを入力（<strong>Traeでも以下の操作が可能</strong>）して、GitHubがデバイスを識別できるかテスト：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com</span></span></code></pre></div><ul><li>Hi [your GitHub username]! You&#39;ve successfully authenticated...のような内容が表示されれば、鍵のバインドは成功；</li><li>エラーが発生した場合、通常は公開鍵のコピーが不完全、秘密鍵の権限が高すぎる（ローカルの~/.ssh/ディレクトリは自分のみが読み書き可能にすべき）などが原因です。必要に応じてこれらの問題を確認してください。</li></ul><h3 id="重要な注意事項" tabindex="-1">重要な注意事項 <a class="header-anchor" href="#重要な注意事項" aria-label="Permalink to “重要な注意事項”">​</a></h3><p>複数のデバイス（ノートPCやデスクトップなど）を持っている場合、各デバイスに対して個別のSSH鍵ペアを生成し、各公開鍵を同じGitHubアカウントにバインドする必要があります——各デバイスには独自の「セキュリティカード」があります。</p><p>秘密鍵を共有しないでください（GitHubにアップロードしたり他人と共有しない）。そうしないと、誰かがあなたになりすましてリポジトリを操作する可能性があります。秘密鍵が漏洩した場合は、GitHubから対応する公開鍵を直ちに削除し、新しい鍵ペアを生成してください。</p><p>SSHをバインドした後、操作にはSSH形式のリポジトリアドレス（例：git@github.com:username/repository.git）を使用し、HTTPS形式（例：<a href="https://github.com/username/repository.git%EF%BC%89%E3%81%AF%E4%BD%BF%E7%94%A8%E3%81%97%E3%81%AA%E3%81%84%E3%81%A7%E3%81%8F%E3%81%A0%E3%81%95%E3%81%84%E3%80%82%E4%BB%A5%E5%89%8D%E3%81%ABHTTPS%E3%81%A7%E3%83%AA%E3%83%9D%E3%82%B8%E3%83%88%E3%83%AA%E3%82%92%E3%82%AF%E3%83%AD%E3%83%BC%E3%83%B3%E3%81%97%E3%81%9F%E5%A0%B4%E5%90%88%E3%81%AF%E3%80%81git" target="_blank" rel="noreferrer">https://github.com/username/repository.git）は使用しないでください。以前にHTTPSでリポジトリをクローンした場合は、git</a> remote set-url origin <code>&lt;new&gt;</code>でプロトコルを切り替えられます。</p><h1 id="traeでgithub操作を行う" tabindex="-1">TraeでGitHub操作を行う <a class="header-anchor" href="#traeでgithub操作を行う" aria-label="Permalink to “TraeでGitHub操作を行う”">​</a></h1><p>Gitとは何か、GitHubとは何か、SSHとは何か、そしてその設定方法について説明しました。これでTraeを使って自由にGit操作を行えます。まず、リモートリポジトリをローカルマシンにクローンする方法を学びましょう。</p><h2 id="git-clone-既存のリポジトリをダウンロード" tabindex="-1">Git clone：既存のリポジトリをダウンロード <a class="header-anchor" href="#git-clone-既存のリポジトリをダウンロード" aria-label="Permalink to “Git clone：既存のリポジトリをダウンロード”">​</a></h2><p>クローンしたいリポジトリのアドレスを直接伝えることができます</p><p><img src="'+_+'" alt=""></p><h2 id="git-pull-リモートリポジトリから更新を取得" tabindex="-1">Git pull：リモートリポジトリから更新を取得 <a class="header-anchor" href="#git-pull-リモートリポジトリから更新を取得" aria-label="Permalink to “Git pull：リモートリポジトリから更新を取得”">​</a></h2><p>リポジトリを更新する前に、複数人でメンテナンスされている可能性があるため、まず最新の変更をプルする必要があります。その後、ファイルを修正してプッシュできます。</p><p><strong>間違ったリポジトリにプッシュしないよう、フォルダ名とその相対パスまたは絶対パスを必ず含めてください。</strong></p><p>prompt:<code>Help me pull this repository AIID-TEST in ./AIID-TEST.</code></p><h2 id="git-commit-git-push-更新をステージしてgithubにプッシュ" tabindex="-1">Git commit &amp; Git push：更新をステージしてGitHubにプッシュ <a class="header-anchor" href="#git-commit-git-push-更新をステージしてgithubにプッシュ" aria-label="Permalink to “Git commit &amp; Git push：更新をステージしてGitHubにプッシュ”">​</a></h2><p>すべての準備が整ったら、ローカルファイルの修正、フォルダ内のアイテムの追加や削除を試みてください。その後、Traeに変更を検出させ、GitHubへのプッシュを支援させます。</p><p>prompt:<code>I finished. Commit and push to the repository AIID-TEST in ./AIID-TEST.</code></p><p><img src="'+E+'" alt=""></p><p>プッシュ成功。これでGitHubで更新された内容を確認できます。</p><h1 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to “参考資料”">​</a></h1><ul><li>Pro Git book <a href="https://git-scm.com/book/en/v2" target="_blank" rel="noreferrer">https://git-scm.com/book/en/v2</a></li><li>GitHub Docs <a href="https://docs.github.com/en" target="_blank" rel="noreferrer">https://docs.github.com/en</a></li></ul>',92)])])}const j=a(C,[["render",x]]);export{D as __pageData,j as default};
